select #{uid} uid, s.id,u.user_name userName,d.dept_name dname,p.dept_name yname, s.user_id, s.top_name, s.top_type, s.signing_data, s.validity_Date, s.first_person_id, s.second_person_id, s.third_person_id, fourth_person_id, concat( s.amount,'万') amount, s.contract, s.filing, s.state ,s.PA ,s.PB from sci_IntraSchPro_apply s left join sys_user u on s.user_id=u.user_id left join sys_dept d on u.dept_id = d.dept_id left join sys_dept p on d.parent_id =p.dept_id where s.state =6
and top_name like concat('%', #{topName}, '%') and d.dept_name like concat('%', #{dname}, '%') and user_name like concat('%', #{userName}, '%') and state = #{state} and YEAR(DATE_ADD(signing_data,INTERVAL 1 MONTH)) = #{year}
