select 'admin' role,#{uid} uid, s.id,u.user_name userName,d.dept_name dname,p.dept_name yname, s.user_id, s.top_name, s.top_type, s.signing_data, s.validity_Date, s.first_person_id, s.second_person_id, s.third_person_id, fourth_person_id, concat( s.amount,'万') amount, s.contract, s.filing, s.state ,s.PA ,s.PB from sci_IntraSchPro_apply s left join sys_user u on s.user_id=u.user_id left join sys_dept d on u.dept_id = d.dept_id left join sys_dept p on d.parent_id =p.dept_id where s.state in (7,8,9,10)
and top_name like concat('%', #{topName}, '%') and d.dept_name like concat('%', #{dname}, '%') and user_name like concat('%', #{userName}, '%') and state = #{state} and YEAR(DATE_ADD(signing_data,INTERVAL 1 MONTH)) = #{year}
order by createtime desc

  select
  'dept_teacher' role,#{uid} uid, s.id,u.user_name userName,d.dept_name dname,p.dept_name yname, s.user_id, s.top_name, s.top_type,
  s.signing_data, s.validity_Date, s.first_person_id,  s.second_person_id, s.third_person_id, fourth_person_id,
  concat( s.amount,'万') amount, s.contract, s.filing, s.state ,s.PA ,s.PB
  from sci_IntraSchPro_apply s left join sys_user u on  s.user_id=u.user_id
  left join sys_dept d on u.dept_id = d.dept_id
  left join sys_dept p on d.parent_id =p.dept_id
  where s.state in (11,2) and d.dept_name in (SELECT dept_name from sys_dept where parent_id = (SELECT parent_id from sys_dept WHERE dept_id=(SELECT dept_id from sys_user WHERE user_id= #{uid})))
   and top_name like concat('%', #{topName}, '%')
   and d.dept_name like concat('%', #{dname}, '%')
   and user_name like concat('%', #{userName}, '%')
   and state = #{state}

   and YEAR(DATE_ADD(signing_data,INTERVAL 1 MONTH)) = #{year}



or (
s.user_id = #{uid}
OR s.first_person_id = #{uid}
OR s.second_person_id = #{uid}
OR s.third_person_id = #{uid}
OR s.fourth_person_id = #{uid}
)




  order  by createtime desc

select 'dept_teacher' role,#{uid} uid, s.id,u.user_name userName,d.dept_name dname,p.dept_name yname, s.user_id, s.top_name, s.top_type, s.signing_data, s.validity_Date, s.first_person_id, s.second_person_id, s.third_person_id, fourth_person_id, concat( s.amount,'万') amount, s.contract, s.filing, s.state ,s.PA ,s.PB, MAX(CASE WHEN s.first_person_id = sc.userid AND s.id = sc.sciIntraSch_Id THEN sc.earnedJT_Points END) AS firstPoints, MAX(CASE WHEN s.second_person_id = sc.userid AND s.id = sc.sciIntraSch_Id THEN sc.earnedJT_Points END) AS secondPoints, MAX(CASE WHEN s.third_person_id = sc.userid AND s.id = sc.sciIntraSch_Id THEN sc.earnedJT_Points END) AS thirdPoints, MAX(CASE WHEN s.fourth_person_id = sc.userid AND s.id = sc.sciIntraSch_Id THEN sc.earnedJT_Points END) AS forthPoints from sci_IntraSchPro_apply s left join sys_user u on s.user_id=u.user_id left join sys_dept d on u.dept_id = d.dept_id left join sys_dept p on d.parent_id =p.dept_id LEFT JOIN sci_IntraSchPro_score sc ON sc.sciIntraSch_Id = s.id where s.state in (13,8) and d.dept_name in (SELECT dept_name from sys_dept where parent_id = (SELECT parent_id from sys_dept WHERE dept_id=(SELECT dept_id from sys_user WHERE user_id= #{uid})))
and top_name like concat('%', #{topName}, '%') and d.dept_name like concat('%', #{dname}, '%') and user_name like concat('%', #{userName}, '%') and state = #{state}
and YEAR(DATE_ADD(signing_data,INTERVAL 1 MONTH)) = #{year}
OR ( ( s.user_id = #{uid} OR s.first_person_id = #{uid} OR s.second_person_id = #{uid} OR s.third_person_id = #{uid} OR s.fourth_person_id = #{uid} )and s.state IN ( 13, 8 ) )
GROUP BY s.id, u.user_name, d.dept_name, p.dept_name, s.user_id, s.top_name, s.top_type, s.signing_data, s.validity_Date, s.first_person_id, s.second_person_id, s.third_person_id, s.fourth_person_id, CONCAT(s.amount, '万'), s.contract, s.filing, s.state, s.PA, s.PB order by createtime desc
